  if ('layoutMode' in n && n.layoutMode !== 'NONE') s += ' L' + n.layoutMode[0];
  if (Array.isArray(n.strokes) && n.strokes.length) { const f = n.strokes[0]; s += ' S:' + (f.boundVariables && f.boundVariables.color ? '$' + await vn(f.boundVariables.color.id) : f.type) + '/' + (typeof n.strokeWeight === 'number' ? n.strokeWeight : 'mixed'); }
  if (n.type === 'TEXT') s += ' "' + n.characters.slice(0, 30) + '" refs=' + JSON.stringify(n.componentPropertyReferences || {});
  if (n.explicitVariableModes && Object.keys(n.explicitVariableModes).length) s += ' modes';
  if (n.type === 'INSTANCE') { const m = await n.getMainComponentAsync(); return [s + ' <' + (m.parent && m.parent.type === 'COMPONENT_SET' ? m.parent.name + ':' : '') + m.name + '>']; }
  const out = [s]; if ('children' in n) for (const c of n.children) out.push(...await desc(c, d + 1)); return out;
